using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using System.Web.Script.Serialization;

// Explicitly owner-visible, bounded input-metadata instrument. Never reads RAWKEYBOARD,
// RAWMOUSE, key codes, buttons, text, or input payload bytes; no device-control calls.
public sealed class UsbHidRawInputProbe:Form {
 public sealed class Counter {
  public string Reference,Name;public int BaselineEvents,TestEvents;public long FirstMs=-1,LastMs=-1,TestFirstMs=-1,TestLastMs=-1;
  public string Evidence{get{return BaselineEvents==0?"Baseline missing":TestEvents>0?"Input observed during test":"No test input observed; fixture attempt must be independently confirmed";}}
 }
 public sealed class Counts {
  public string Phase="idle";public long BaselineMarkerMs=-1,TestMarkerMs=-1;public int Unresolved,Omitted;readonly Dictionary<string,Counter> rows=new Dictionary<string,Counter>();
  public Counter[] Rows{get{return rows.Values.ToArray();}}
  public void Marker(string phase,long ms){if(ms<0||ms>120000||(phase!="baseline"&&phase!="test"))throw new InvalidOperationException("Invalid marker");if(phase=="test"&&BaselineMarkerMs<0)throw new InvalidOperationException("Begin baseline first");Phase=phase;if(phase=="baseline"){BaselineMarkerMs=ms;TestMarkerMs=-1;foreach(var row in rows.Values){row.BaselineEvents=0;row.TestEvents=0;row.FirstMs=-1;row.LastMs=-1;row.TestFirstMs=-1;row.TestLastMs=-1;}}else {TestMarkerMs=ms;foreach(var row in rows.Values){row.TestEvents=0;row.TestFirstMs=-1;row.TestLastMs=-1;}}}
  public void Record(string reference,string name,long ms){if(Phase=="idle"||ms<0||ms>120000)return;if(reference==null){Unresolved=Math.Min(1000000,Unresolved+1);return;}Counter row;if(!rows.TryGetValue(reference,out row)){if(rows.Count>=128){Omitted=Math.Min(1000000,Omitted+1);return;}row=new Counter{Reference=reference,Name=UsbAdmissionInventory.Display(name)};rows.Add(reference,row);}if(Phase=="baseline")row.BaselineEvents=Math.Min(1000000,row.BaselineEvents+1);else {row.TestEvents=Math.Min(1000000,row.TestEvents+1);if(row.TestFirstMs<0)row.TestFirstMs=ms;row.TestLastMs=ms;}if(row.FirstMs<0)row.FirstMs=ms;row.LastMs=ms;}
 }
 [StructLayout(LayoutKind.Sequential)]struct Registration{public ushort Page,Usage;public uint Flags;public IntPtr Target;}
 [StructLayout(LayoutKind.Sequential)]struct Header{public uint Type,Size;public IntPtr Device,Parameter;}
 [StructLayout(LayoutKind.Sequential)]struct Key{public Guid Format;public uint Id;}
 [DllImport("user32.dll",SetLastError=true)]static extern bool RegisterRawInputDevices(Registration[] devices,uint count,uint size);
 [DllImport("user32.dll")]static extern uint GetRawInputData(IntPtr input,uint command,IntPtr data,ref uint size,uint headerSize);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern uint GetRawInputDeviceInfoW(IntPtr device,uint command,IntPtr buffer,ref uint size);
 [DllImport("cfgmgr32.dll",CharSet=CharSet.Unicode)]static extern uint CM_Get_Device_Interface_PropertyW(string path,ref Key key,out uint type,byte[] data,ref uint size,uint flags);
 [DllImport("cfgmgr32.dll",CharSet=CharSet.Unicode)]static extern uint CM_Locate_DevNodeW(out uint node,string id,uint flags);
 [DllImport("cfgmgr32.dll")]static extern uint CM_Get_Parent(out uint parent,uint node,uint flags);
 [DllImport("cfgmgr32.dll",CharSet=CharSet.Unicode)]static extern uint CM_Get_Device_IDW(uint node,StringBuilder id,uint size,uint flags);
 readonly Counts counts=new Counts();readonly Stopwatch clock=Stopwatch.StartNew();readonly Timer timer=new Timer();readonly TextBox output=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill};readonly Dictionary<string,string> references=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);readonly Dictionary<IntPtr,Tuple<string,string>> mapped=new Dictionary<IntPtr,Tuple<string,string>>();bool listening;string status="Read-only observer";
 public UsbHidRawInputProbe(){Text="Sentinel — USB input acceptance counts";Width=880;Height=520;StartPosition=FormStartPosition.CenterScreen;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=88};top.Controls.Add(new Label{Text="Two-minute metadata-only observation. Positive baseline + independently attempted input required.\nCounts alone never prove blocking. No keys, mouse buttons or typed text are recorded.",AutoSize=true,MaximumSize=new Size(840,50)});var baseline=new Button{Text="Begin baseline",AutoSize=true};baseline.Click+=(s,e)=>Mark("baseline");var test=new Button{Text="Begin test",AutoSize=true};test.Click+=(s,e)=>Mark("test");var save=new Button{Text="Save report",AutoSize=true};save.Click+=(s,e)=>Save();top.Controls.Add(baseline);top.Controls.Add(test);top.Controls.Add(save);Controls.Add(output);Controls.Add(top);Shown+=(s,e)=>{var registration=new[]{new Registration{Page=1,Usage=6,Flags=0x2100,Target=Handle},new Registration{Page=1,Usage=2,Flags=0x2100,Target=Handle}};listening=RegisterRawInputDevices(registration,2,(uint)Marshal.SizeOf(typeof(Registration)));if(!listening)status="Raw input registration failed";timer.Interval=250;timer.Tick+=(a,b)=>Render();timer.Start();};FormClosed+=(s,e)=>{timer.Stop();Unregister();};}
 void Unregister(){if(!listening)return;RegisterRawInputDevices(new[]{new Registration{Page=1,Usage=6,Flags=1,Target=IntPtr.Zero},new Registration{Page=1,Usage=2,Flags=1,Target=IntPtr.Zero}},2,(uint)Marshal.SizeOf(typeof(Registration)));listening=false;}
 void Mark(string phase){try{counts.Marker(phase,clock.ElapsedMilliseconds);status="Marker: "+phase;}catch(InvalidOperationException){status="Begin baseline first; session expires after two minutes";}Render();}
 void Render(){if(clock.ElapsedMilliseconds>120000){Unregister();status="Observation finished (two-minute bound)";}var text=new StringBuilder(status+" | "+Math.Min(120000,clock.ElapsedMilliseconds)+" ms\r\n");foreach(var row in counts.Rows)text.AppendLine(row.Reference+" | "+row.Name+" | baseline "+row.BaselineEvents+" | test "+row.TestEvents+" | first/last "+row.FirstMs+"/"+row.LastMs+" ms | "+row.Evidence);text.AppendLine("Unresolved: "+counts.Unresolved+"; omitted: "+counts.Omitted);output.Text=text.ToString();}
 void Save(){var report=new {mode="metadata_only_owner_observation",policyChanged=false,blockingProven=false,elapsedMs=Math.Min(120000,clock.ElapsedMilliseconds),baselineMarkerMs=counts.BaselineMarkerMs,testMarkerMs=counts.TestMarkerMs,unresolved=counts.Unresolved,omitted=counts.Omitted,devices=counts.Rows};File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"usb-hid-input-counts.json"),new JavaScriptSerializer().Serialize(report));status="Report saved (no device IDs or input content)";Render();}
 string Map(IntPtr handle,out string name){Tuple<string,string> cached;if(mapped.TryGetValue(handle,out cached)){name=cached.Item2;return cached.Item1;}name="Unresolved input";if(handle==IntPtr.Zero)return null;uint n=0;if(GetRawInputDeviceInfoW(handle,0x20000007,IntPtr.Zero,ref n)==uint.MaxValue||n<2||n>1024)return null;IntPtr b=Marshal.AllocHGlobal((int)n*2);string path;try{uint cap=n;if(GetRawInputDeviceInfoW(handle,0x20000007,b,ref n)==uint.MaxValue||n>cap)return null;path=Marshal.PtrToStringUni(b,(int)n).TrimEnd('\0');}finally{Marshal.FreeHGlobal(b);}var key=new Key{Format=new Guid("78c34fc8-104a-4aca-9ea4-524d52996e57"),Id=256};byte[] value=new byte[1024];uint size=1024,type;if(CM_Get_Device_Interface_PropertyW(path,ref key,out type,value,ref size,0)!=0||type!=0x12||size<2||size>1024||size%2!=0)return null;string id=Encoding.Unicode.GetString(value,0,(int)size).TrimEnd('\0');uint node;if(CM_Locate_DevNodeW(out node,id,0)!=0)return null;var chain=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var nodes=new HashSet<uint>();for(int depth=0;depth<12&&nodes.Add(node);depth++){var text=new StringBuilder(513);if(CM_Get_Device_IDW(node,text,513,0)!=0)return null;chain.Add(text.ToString());uint parent;if(CM_Get_Parent(out parent,node,0)!=0)break;node=parent;}var inventory=UsbAdmissionInventory.Collect(null);if(!inventory.Complete||inventory.Subjects==null)return null;var matched=inventory.Subjects.Where(s=>chain.Contains(s.Input.Instance)).ToArray();if(matched.Length!=1)return null;name=matched[0].DisplayName;string reference;if(!references.TryGetValue(matched[0].Input.Instance,out reference)){if(references.Count>=128)return null;reference="input-"+Guid.NewGuid().ToString("N");references.Add(matched[0].Input.Instance,reference);}mapped[handle]=Tuple.Create(reference,name);return reference;}
 protected override void WndProc(ref Message m){if(m.Msg==0x00fe)mapped.Clear();if(m.Msg==0x00ff&&listening&&clock.ElapsedMilliseconds<=120000&&counts.Phase!="idle"){uint n=(uint)Marshal.SizeOf(typeof(Header));IntPtr buffer=Marshal.AllocHGlobal((int)n);try{uint cap=n;if(GetRawInputData(m.LParam,0x10000005,buffer,ref cap,n)==n){var header=(Header)Marshal.PtrToStructure(buffer,typeof(Header));if(header.Type<=1){long arrivalMs=clock.ElapsedMilliseconds;string name,reference=Map(header.Device,out name);if(mapped.Count<128)mapped[header.Device]=Tuple.Create(reference,name);counts.Record(reference,name,arrivalMs);}}}catch{counts.Record(null,null,clock.ElapsedMilliseconds);}finally{Marshal.FreeHGlobal(buffer);}}base.WndProc(ref m);}
 static int Test(){var c=new Counts();c.Record("x","test",1);if(c.Rows.Length!=0)return 1;try{c.Marker("test",1);return 2;}catch(InvalidOperationException){}c.Marker("baseline",5);c.Record("x","test",6);if(c.Rows[0].BaselineEvents!=1||c.Rows[0].FirstMs!=6)return 3;c.Marker("test",8);if(!c.Rows[0].Evidence.Contains("independently"))return 8;c.Record("x","test",9);if(c.Rows[0].TestEvents!=1||c.Rows[0].Evidence!="Input observed during test")return 4;c.Record("x","test",120001);if(c.Rows[0].TestEvents!=1)return 5;for(int i=0;i<130;i++)c.Record("id"+i,"test",10);if(c.Rows.Length!=128||c.Omitted!=3)return 6;c.Marker("baseline",11);if(c.Rows.Any(r=>r.BaselineEvents!=0||r.TestEvents!=0))return 7;Console.WriteLine("PASS raw-input metadata marker/count bounds");return 0;}
 [STAThread]public static int Main(string[] args){if(args.Length==1&&args[0]=="--self-test")return Test();if(args.Length!=0)return 2;Application.EnableVisualStyles();Application.Run(new UsbHidRawInputProbe());return 0;}
}


